import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"3.0.0-WP-tui-input-encoding-hardening — TUI 输入与编码加固","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/3.0.0-WP-tui-input-encoding-hardening.md","filePath":"zh/release/3.0.0-WP-tui-input-encoding-hardening.md"}'),d={name:"zh/release/3.0.0-WP-tui-input-encoding-hardening.md"};function n(r,e,c,l,u,h){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="_3-0-0-wp-tui-input-encoding-hardening-—-tui-输入与编码加固" tabindex="-1">3.0.0-WP-tui-input-encoding-hardening — TUI 输入与编码加固 <a class="header-anchor" href="#_3-0-0-wp-tui-input-encoding-hardening-—-tui-输入与编码加固" aria-label="Permalink to &quot;3.0.0-WP-tui-input-encoding-hardening — TUI 输入与编码加固&quot;">​</a></h1><p>输入/编码/显示加固批次：五个用户上报缺陷逐一追到根因，每一项都有 复现证据；其后对三条链路做了全量扫描。所有修复遵循&quot;标准纪律、 零平台特判&quot;原则。</p><h2 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to &quot;变更&quot;">​</a></h2><h3 id="_1-tui-入口隐藏-保留注册、仅不再列出" tabindex="-1">1. TUI 入口隐藏（保留注册、仅不再列出） <a class="header-anchor" href="#_1-tui-入口隐藏-保留注册、仅不再列出" aria-label="Permalink to &quot;1. TUI 入口隐藏（保留注册、仅不再列出）&quot;">​</a></h3><p>八个旧式 TUI 子启动器（<code>tui-test</code>、<code>tui-hw</code>、<code>tui-net</code>、 <code>tui-sysinfo</code>、<code>tui-time</code>、<code>tui-drv</code>、<code>tui-sys</code>、<code>tui-ext</code>）保持 注册且可直接执行——只是不再&quot;列出&quot;：<code>help</code> 与 <code>help -a</code> 不再显示， 桌面树移除了扩展实验室镜像节点，对账口径为 311 注册 / 292 列出 / 8 隐藏（呈现门禁同时断言两个数字）。未删除任何代码路径；唯一 事实源是 <code>l1_tui_entry_filter.c</code> 中的 <code>k_hidden[]</code> 表。</p><h3 id="_2-ocire-空格捕获-根因-扫描码表越界" tabindex="-1">2. OCIRE 空格捕获（根因：扫描码表越界） <a class="header-anchor" href="#_2-ocire-空格捕获-根因-扫描码表越界" aria-label="Permalink to &quot;2. OCIRE 空格捕获（根因：扫描码表越界）&quot;">​</a></h3><p><code>lang zh</code> 打成 <code>LANGZH</code>、带空格命令全部失效：PS/2 扫描码解码器 查表越界一格——空格键的通码（0x39）落表外，把相邻内存当作 ASCII 映射读出。在表上修复；六路径矩阵（OCIRE 与 OCOS × 串口、PS/2、 UEFI）全绿，含 <code>LANG ZH</code>、<code>LANG EN</code> 与所有带空格命令。</p><h3 id="_3-跨写入-utf-8-tty" tabindex="-1">3. 跨写入 UTF-8 TTY <a class="header-anchor" href="#_3-跨写入-utf-8-tty" aria-label="Permalink to &quot;3. 跨写入 UTF-8 TTY&quot;">​</a></h3><p>ush 行编辑器对每个按键事件做单字节 write 回显；粘贴或输入法上屏 的汉字以 3-4 个这样的写到达，而控制台路径对每个写独立解码—— 孤立前导字节被按 Latin-1 画格，每个汉字都回显成实心方块，直到 整行重绘才偶然修复。TTY 现在跨写重组多字节序列 （<code>core_tty_utf8.c</code>）：接收与回显字节精确；<code>cat</code> UTF-8 文件返回 精确序列；退格删整个字符（线上可见 2 格擦除）；80 格换行不切分 字形；步进按&quot;字符&quot;计。证据含 VLM 读屏的 VGA 截图与原始字节 hexdump。明确不做（维持设计边界）：输入法、locale 体系、文件名 规范化。</p><h3 id="_4-串口编码方向-裁定-无代码变更" tabindex="-1">4. 串口编码方向（裁定，无代码变更） <a class="header-anchor" href="#_4-串口编码方向-裁定-无代码变更" aria-label="Permalink to &quot;4. 串口编码方向（裁定，无代码变更）&quot;">​</a></h3><p>两条串口路径的原始字节捕获：内核输出全部为合法 UTF-8，OCBL 只发 纯 ASCII + 标准 ANSI CSI（与 GRUB 串口菜单相同的序列），内建 <code>serial_encoding=gbk</code> tee 双向转换正确。上报的&quot;COM1 乱码&quot;是宿主 终端解码所致——报告者的 Windows 宿主运行 windows-936（GBK）代码页 读 UTF-8 流。登记，非代码缺陷。</p><h3 id="_5-vmware-三重故障修复-五项发现、四项代码修复" tabindex="-1">5. VMware 三重故障修复（五项发现、四项代码修复） <a class="header-anchor" href="#_5-vmware-三重故障修复-五项发现、四项代码修复" aria-label="Permalink to &quot;5. VMware 三重故障修复（五项发现、四项代码修复）&quot;">​</a></h3><p>交付的 <code>vmware.log</code>（15 次 <code>Triple fault.</code>，每周期约 1.24 秒）与 启动串口被推成完整推理链（逐字引用、崩溃阶段映射与假设矩阵见 <code>evidence/.../vmware/vmware-reasoning.md</code>）：</p><ul><li><strong>H1 - OCBL 核心从未装载 IDT。</strong> 64 位核心继承了固件实模式 IVT 状态（<code>{0, 0x3FF}</code>），长模式下任何向量化都会误读——异步事件 升级为 #GP → #DF → 三重故障。OCBL 现在自建 256 门表 （<code>ocbl_idt.c/.S/.h</code>）：异常上串口报告并停机，IRQ/NMI 走 iretq；实模式蹦床在每个模式边界交换向量化纪律（下行恢复固件 IVT、上行恢复自有表）。不依赖 VMware 的决定性证明：在纯 64 位 OCBL 代码断点处注入 NMI，修复前构建死亡（复位路径），修复后 构建吸收。</li><li><strong>H2 - El Torito 引导驱动器号由固件自选</strong>（报告者的 VMware 传 0x9F 而非 0xE0+）：扫描永远看不到引导 CD，菜单回退到关机倒 计时。现按 El Torito 类型判定。</li><li><strong>H3 - 状态监视器的 EBDA 守卫读的是 I/O 端口而非 BDA 内存字</strong>， 因此从未触发，状态页可能落进 BIOS 私有低内存（&quot;下一次 INT 调用 三重故障&quot;类）。强制构建证明：守卫触发、内核遵循 <code>oc.stmon=off</code>、引导完成。</li><li><strong>H4 - 低 EBDA 机器的页表重定位目标落在蹦床自身地址上</strong>，且返 回路径硬编码 CR3。重定位目标迁移并单一事实源发布；强制构建 矩阵：新目标可引导，旧目标在修复前后构建上都死。</li><li>另有：CMOS 寄存器选择保持 NMI 掩码置位；UEFI getkey 接纳 OVMF ConIn 可能窃取的 CSI 方向键尾字节。</li></ul><h3 id="_6-扩展排查" tabindex="-1">6. 扩展排查 <a class="header-anchor" href="#_6-扩展排查" aria-label="Permalink to &quot;6. 扩展排查&quot;">​</a></h3><p>对最终树的三链路复审计。BIOS 菜单串口键控原本失效（SeaBIOS 下 int 14h 路径永不送达）——现改为直读 16550，实测验证。本批次自身 的一处回归（在 UEFI 下装载我们的 IDT 会杀死 OVMF 的中断驱动生态） 在发布前被捕获并修复——IDT 装载仅限 BIOS 固件。OVMF 菜单输入 饥饿登记为 K-06 并附规避方案。</p><h2 id="验证-全部在发布构建上" tabindex="-1">验证（全部在发布构建上） <a class="header-anchor" href="#验证-全部在发布构建上" aria-label="Permalink to &quot;验证（全部在发布构建上）&quot;">​</a></h2><ul><li><code>make all</code>：0 错误 0 编译警告（1 条已文档化的 ld RWX 提示）； reproducible-check PASS（两次干净构建逐字节一致）</li><li>31/31 运行时回归（命令数下限 292——隐藏后的列出口径）</li><li>WP-08 驱动框架门禁：43/43</li><li>dhtest：5/5 正确性 + 确定性 IDENTICAL</li><li>SSH E2E：ALL PASS；HTTPS E2E：8/8</li><li>verify_presentation：ALL CHECKS PASS（字典 311/292 双口径、 事实源、隐私、豁免登记）</li><li>BIOS + UEFI 引导：横幅 <code>3.0.0-WP-tui-input-encoding-hardening</code> build 478 + ring-3 ush&gt; + 引导完成</li><li>空格矩阵（六路径）与 UTF-8 链（7/7）在最终树上复跑全绿</li></ul><h2 id="已知问题" tabindex="-1">已知问题 <a class="header-anchor" href="#已知问题" aria-label="Permalink to &quot;已知问题&quot;">​</a></h2><ul><li><strong>K-06 - 引导服务存活期间 OVMF 下的 OCBL 菜单无法通过键盘操 作。</strong> 无任何输入源送达（串口字节被 OVMF 终端驱动抽干且不再经 ConIn 回流；PS/2 同样饥饿）——菜单在 10 秒倒计时后自动引导默认 条目。BIOS 侧菜单键盘操作完整可用（串口 + PS/2）。候选后续修 复：基于 WaitForEvent 的菜单等待循环。</li><li>K-01/K-02/K-03/K-05 原样结转（见 KNOWN_ISSUES）。</li></ul><p>证据：<code>evidence/wp-tui-input-encoding-hardening/</code>（串口原始字节 捕获与 hexdump 分析、VMware 推理链及全部测试转录、扩展排查发现、 回归门禁捕获）。</p>',21)])])}const _=o(d,[["render",n]]);export{p as __pageData,_ as default};
